        $teamPivot = $this->assignedModelsTeamPivot();

        foreach ($collection->groupBy(fn (Model $model) => $model::class) as $class => $group) {
            $this->assignedModelsRelation($class)->syncWithoutDetaching(
                $group->mapWithKeys(fn (Model $model) => [$model->getKey() => $teamPivot])->all()
